output_text:
[
  {
    "id": "must_take_cart_first",
    "text": "A shopper is obliged to take the available cart from the cart station before doing the shopping.",
    "abstraction": {
      "state_properties": {
        "cart_station_cell": "at(1,5)",
        "cart_available_at_station": {
          "and": [
            "cart_station_cell",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_cart_from_station": {
          "pre": {
            "and": [
              "cart_available_at_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_station"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A shopper is prohibited from picking up merchandise unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {
        "product_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "product_pickup",
          {
            "not": "cart_in_possession"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying groceries by hand rather than transporting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "pickup_that_would_fill_hand": {
          "pre": "PICKUP_ITEM",
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_to_front_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the front return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "cart_returned_at_front_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_at_front_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "leave_cart_only_at_bay",
    "text": "A shopper is prohibited from leaving the cart anywhere except the designated return bay at the front.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "designated_cart_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "A shopper is prohibited from exiting unless the cart has already been parked at the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_front_bay": "cartAt(0,1)"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          {
            "not": "cart_parked_at_front_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_front_exit_walkway",
    "text": "Carts are prohibited in the front exit walkway east of the cart return bay, so shoppers must continue to the exit without the cart.",
    "abstraction": {
      "state_properties": {
        "front_exit_walkway_east_of_bay": {
          "or": [
            "at(2,1)",
            "at(3,1)",
            "at(4,1)",
            "at(5,1)",
            "at(6,1)",
            "at(7,1)",
            "at(8,1)",
            "at(9,1)"
          ]
        },
        "cart_in_front_exit_walkway": {
          "and": [
            "hasCart",
            "front_exit_walkway_east_of_bay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_front_exit_walkway"
    }
  },
  {
    "id": "no_cart_in_lower_middle_aisle",
    "text": "Carts are prohibited in the lower middle aisle, although shoppers may walk there after returning the cart.",
    "abstraction": {
      "state_properties": {
        "lower_middle_aisle": {
          "or": [
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)"
          ]
        },
        "cart_in_lower_middle_aisle": {
          "and": [
            "hasCart",
            "lower_middle_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_lower_middle_aisle"
    }
  }
]
